insert into "reports" ("assignee_admin_id", "service_id", "service_code", "reporter_name", "reporter_contact", "title", "description", "address", "city", "district", "category", "priority", "created_at", "updated_at", "statuses", "review_timestamps", "reviewing_admin_ids", "review_notes", "agreements_history", "disagreements_history") values ('48', '8', 'DINKES', 'Jasmin Maryati', '(+62) 20 5575 0173', 'Et commodi eum explicabo quis.', 'Dolores suscipit ea delectus hic blanditiis accusantium. Perspiciatis vero ipsum odit et et. Voluptatem ut dolor facilis dolorem quasi amet commodi maxime.', 'Psr. Dahlia No. 810', 'Sibolga', 'Maluku', 'Pertanian dan Ketahanan Pangan', 'high', '2025-11-08 03:02:00', '2025-11-12 13:45:38', '[\"pending\",\"process\",\"process\",\"process\",\"finished\"]', '[\"2025-11-08 03:02:00\",\"2025-11-08 15:38:39\",\"2025-11-12 02:04:03\",\"2025-11-12 03:43:51\",\"2025-11-12 13:45:38\"]', '[9,60,77,64,27]', '[\"Voluptatibus rerum quisquam recusandae itaque saepe veritatis repudiandae.\",\"In harum at est ratione nemo sequi quo.\",\"Omnis facere quasi hic sit a animi.\",\"Et magni pariatur sequi voluptatem incidunt qui aut tenetur.\",\"Qui voluptatibus harum cum nesciunt reiciendis sed sequi.\"]', '[3,8,2,1,9]', '[9,9,4,7,4]') returning "id";
insert into "reports" ("assignee_admin_id", "service_id", "service_code", "reporter_name", "reporter_contact", "title", "description", "address", "city", "district", "category", "priority", "created_at", "updated_at", "statuses", "review_timestamps", "reviewing_admin_ids", "review_notes", "agreements_history", "disagreements_history") values ('35', '3', 'DPUSDA', 'Dewi Mandasari', '022 3965 8478', 'Blanditiis recusandae quam enim non quis magni rerum.', 'Consequuntur ut occaecati quam recusandae in. Et debitis eum tenetur sunt eligendi modi temporibus. Eius ducimus deleniti molestiae aspernatur harum est. Iure consequatur suscipit ab voluptatem fuga ad voluptatem.', 'Ds. Gardujati No. 309', 'Lubuklinggau', 'Kalimantan Tengah', 'Perumahan Rakyat, Kawasan Permukiman dan Cipta Karya', 'high', '2025-10-30 14:19:32', '2025-11-09 19:47:58', '[\"pending\",\"process\",\"process\",\"finished\"]', '[\"2025-10-30 14:19:32\",\"2025-10-31 06:24:31\",\"2025-11-09 04:25:59\",\"2025-11-09 19:47:58\"]', '[34,44,98,61]', '[\"Nulla aperiam neque quam perferendis dolore.\",\"Aperiam odit ut nobis quidem autem optio.\",\"Assumenda quisquam qui qui porro qui mollitia iste.\",\"Odit fugit dolor distinctio quae dolor eum magni sed.\"]', '[7,3,7,5]', '[5,8,8,6]') returning "id";
